 * comes from) occurs - null where it does not occur in the Qur'an as such. Written for this app;
 * owed a scholar's review. Every reference was checked against the Qur'an text.
 */
internal data class NameExplanation(
  val quran: String?,
  val texts: Map<AppLanguage, String>
)

