    en = "Al-Alim is the One whose knowledge covers everything, seen and unseen, past and future. Nothing is hidden from Him, not even what hearts conceal.",
    ar = "العليم هو الذي أحاط علمه بكل شيء، ظاهره وخفيّه، ماضيه ومستقبله. لا يخفى عليه ما تخفيه الصدور.",
    bn = "আল-আলীম তিনি, যাঁর জ্ঞান সবকিছুকে ঘিরে আছে, দৃশ্য ও অদৃশ্য, অতীত ও ভবিষ্যৎ। অন্তরে যা গোপন থাকে, তাও তাঁর কাছে অজানা নয়।",
    es = "Al-Alím es Aquel cuyo conocimiento abarca todo, lo visible y lo oculto, el pasado y el futuro. Nada se le escapa, ni siquiera lo que los corazones guardan.",
    pt = "Al-Alim é Aquele cujo conhecimento abrange tudo, o visível e o oculto, o passado e o futuro. Nada Lhe escapa, nem mesmo o que os corações guardam."),
  // 21. Al-Qabid
  explain("2:245",
    en = "Al-Qabid is the One who withholds or narrows provision and life as He sees fit. It is always paired with Al-Basit, since both lie in His wisdom.",
    ar = "القابض هو الذي يقبض الرزق والأرواح بحكمته. ويُذكر دائمًا مع الباسط، فكلاهما بحكمة منه.",
    bn = "আল-কাবিদ তিনি, যিনি নিজের প্রজ্ঞায় রিযিক ও প্রাণ সংকুচিত করেন বা ফিরিয়ে নেন। এই নাম সবসময় আল-বাসিতের সঙ্গে বলা হয়, কারণ দুটোই তাঁর প্রজ্ঞার অংশ।",
    es = "Al-Qábid es Aquel que restringe el sustento y la vida según su sabiduría. Se menciona siempre junto a Al-Básit, porque ambos obedecen a su sabiduría.",
    pt = "Al-Qabid é Aquele que restringe o sustento e a vida conforme a Sua sabedoria. É mencionado sempre junto a Al-Basit, pois ambos obedecem à Sua sabedoria."),
  // 22. Al-Basit
  explain("2:245",
    en = "Al-Basit is the One who extends provision, mercy and life to whomever He wills. Whatever one is given, it is by His generosity.",
    ar = "الباسط هو الذي يبسط الرزق والرحمة لمن يشاء. وما بيد أحد فهو من فضله.",
    bn = "আল-বাসিত তিনি, যিনি যাকে ইচ্ছা তার রিযিক, দয়া ও জীবন প্রসারিত করেন। কেউ যা-ই পায়, তা তাঁর দানেই পায়।",
    es = "Al-Básit es Aquel que extiende el sustento, la misericordia y la vida a quien Él quiere. Todo lo que alguien recibe es por su generosidad.",
    pt = "Al-Basit é Aquele que estende o sustento, a misericórdia e a vida a quem Ele quer. Tudo o que alguém recebe é pela Sua generosidade."),
  // 23. Al-Khafid
  explain(null,
    en = "Al-Khafid is the One who lowers whom He wills, by His justice, such as the arrogant and those who deny the truth. It is the counterpart of Ar-Rafi', and is known from the Prophetic list of Names.",
    ar = "الخافض هو الذي يخفض من يشاء بعدله، كالمتكبرين والمكذبين بالحق. وهو مقابل الرافع، ويُعرف من قائمة الأسماء المروية.",
    bn = "আল-খাফিদ তিনি, যিনি নিজের ন্যায়বিচারে যাকে ইচ্ছা নিচে নামান, যেমন অহংকারী ও সত্য অস্বীকারকারীদের। এটি আর-রাফি'র বিপরীত, আর নামটি বর্ণিত তালিকা থেকে জানা যায়।",
    es = "Al-Jáfid es Aquel que humilla a quien Él quiere, con su justicia, como a los arrogantes y a quienes niegan la verdad. Es el contrapunto de Ar-Ráfi', y se conoce por la lista transmitida de los Nombres.",
    pt = "Al-Khafid é Aquele que rebaixa a quem Ele quer, com a Sua justiça, como os arrogantes e os que negam a verdade. É o contraponto de Ar-Rafi', e é conhecido pela lista transmitida dos Nomes."),
  // 24. Ar-Rafi'
  explain("3:55",
    en = "Ar-Rafi' is the One who raises whom He wills in rank, and who lifted Jesus to Himself. Honor in this world and the next comes only by His raising.",
    ar = "الرافع هو الذي يرفع من يشاء درجات، وقد رفع عيسى عليه السلام إليه. ولا رفعة إلا برفعه.",
    bn = "আর-রাফি' তিনি, যিনি যাকে ইচ্ছা মর্যাদায় উন্নত করেন এবং ঈসা (আ.)-কে নিজের কাছে তুলে নিয়েছেন। দুনিয়া ও আখিরাতের সম্মান তাঁর উন্নতি দান ছাড়া হয় না।",
    es = "Ar-Ráfi' es Aquel que eleva en rango a quien quiere, y que elevó a Jesús hacia Sí. El honor en este mundo y en el otro solo llega por su elevación.",
    pt = "Ar-Rafi' é Aquele que eleva em grau a quem quer, e que elevou Jesus até Si. A honra neste mundo e no outro só chega pela Sua elevação."),
  // 25. Al-Mu'izz
  explain("3:26",
    en = "Al-Mu'izz is the One who grants honor to whomever He wills. True dignity is not in wealth or power but in what He gives.",
    ar = "المعز هو الذي يهب العزة لمن يشاء. فالعزة الحقيقية ليست بالمال ولا بالسلطان، وإنما بما يعطيه.",
    bn = "আল-মু'ইয্য তিনি, যিনি যাকে ইচ্ছা সম্মান দান করেন। প্রকৃত মর্যাদা সম্পদ বা ক্ষমতায় নয়, বরং তাঁর দানেই।",
    es = "Al-Mu'izz es Aquel que concede honor a quien Él quiere. La verdadera dignidad no está en la riqueza ni en el poder, sino en lo que Él da.",
    pt = "Al-Mu'izz é Aquele que concede honra a quem Ele quer. A verdadeira dignidade não está na riqueza nem no poder, mas no que Ele dá."),
  // 26. Al-Mudhill
  explain("3:26",
    en = "Al-Mudhill is the One who brings low whom He wills, by His justice. It always appears beside Al-Mu'izz, to show that honor and disgrace are both in His hand.",
    ar = "المذل هو الذي يُذل من يشاء بعدله. ويقترن بالمعز ليدل على أن العزة والذلة بيده.",
    bn = "আল-মুযিল্ল তিনি, যিনি নিজের ন্যায়বিচারে যাকে ইচ্ছা অপমানিত করেন। সম্মান ও অপমান উভয়ই যে তাঁর হাতে, তা বোঝাতে এটি আল-মু'ইয্যের সঙ্গে আসে।",
    es = "Al-Mudhill es Aquel que humilla a quien quiere, con su justicia. Aparece junto a Al-Mu'izz para mostrar que tanto el honor como la humillación están en su mano.",
    pt = "Al-Mudhill é Aquele que rebaixa a quem quer, com a Sua justiça. Aparece junto a Al-Mu'izz para mostrar que tanto a honra quanto a humilhação estão em Suas mãos."),
  // 27. As-Sami'
  explain("2:127",
    en = "As-Sami' is the One who hears every sound, whether whispered or aloud. No prayer is ever lost to Him, even one only felt in the heart.",
    ar = "السميع هو الذي يسمع كل صوت، سرًّا كان أو جهرًا. فلا يضيع عنده دعاء، ولو كان في القلب.",
    bn = "আস-সামী' তিনি, যিনি প্রতিটি শব্দ শোনেন, ফিসফিসানি হোক বা উচ্চস্বর। কোনো দোয়াই তাঁর কাছে হারায় না, এমনকি যা শুধু অন্তরে অনুভূত হয়।",
    es = "As-Samí' es Aquel que oye todo sonido, susurrado o en voz alta. Ninguna súplica se le pierde, ni siquiera la que solo se siente en el corazón.",
    pt = "As-Sami' é Aquele que ouve todo som, sussurrado ou em voz alta. Nenhuma súplica se perde para Ele, nem mesmo a que apenas se sente no coração."),
  // 28. Al-Basir
  explain("17:1",
    en = "Al-Basir is the One who sees everything, down to the smallest detail. He sees what people do in the open and what they do in secret.",
    ar = "البصير هو الذي يرى كل شيء حتى أدق التفاصيل. يرى ما يعمله الناس علانية وما يعملونه في الخفاء.",
    bn = "আল-বাসীর তিনি, যিনি সবকিছু দেখেন, সবচেয়ে ক্ষুদ্র বিষয়ও। মানুষ প্রকাশ্যে যা করে এবং গোপনে যা করে, সবই তিনি দেখেন।",
    es = "Al-Basír es Aquel que ve todo, hasta el menor detalle. Ve lo que la gente hace en público y lo que hace en secreto.",
    pt = "Al-Basir é Aquele que vê tudo, até o menor detalhe. Vê o que as pessoas fazem em público e o que fazem em segredo."),
  // 29. Al-Hakam
  explain("6:114",
    en = "Al-Hakam is the Judge whose ruling is final and just. The Qur'an says that He is the best one to seek as a judge.",
    ar = "الحكم هو الذي يحكم بين خلقه حكمًا نهائيًا عادلًا. وقد بيّن القرآن أنه خير من يُطلب حكمه.",
    bn = "আল-হাকাম তিনি, যাঁর বিচার চূড়ান্ত ও ন্যায়সংগত। কুরআনে বলা হয়েছে, বিচারক হিসেবে তাঁকেই চাওয়া উচিত।",
    es = "Al-Hakam es el Juez cuyo fallo es final y justo. El Corán dice que es a Él a quien se debe buscar como juez.",
    pt = "Al-Hakam é o Juiz cuja sentença é final e justa. O Alcorão diz que é a Ele que se deve buscar como juiz."),
  // 30. Al-Adl
  explain(null,
    en = "Al-Adl is the One who is perfectly just and wrongs no one, not even by the weight of an atom. This Name is known from the transmitted list, while the Qur'an affirms that He is never unjust to His servants.",
    ar = "العدل هو الذي لا يظلم أحدًا ولو بمثقال ذرة. والاسم معروف من القائمة المروية، والقرآن يؤكد أنه ليس بظلام للعبيد.",
    bn = "আল-আদল তিনি, যিনি পরিপূর্ণ ন্যায়পরায়ণ এবং কারও প্রতি বিন্দুমাত্র অন্যায় করেন না। নামটি বর্ণিত তালিকা থেকে জানা যায়, আর কুরআন নিশ্চিত করে যে তিনি বান্দাদের প্রতি জালিম নন।",
    es = "Al-Adl es Aquel que es perfectamente justo y no comete injusticia con nadie, ni siquiera del peso de un átomo. Este Nombre se conoce por la lista transmitida, y el Corán afirma que Él nunca es injusto con sus siervos.",
    pt = "Al-Adl é Aquele que é perfeitamente justo e não comete injustiça com ninguém, nem mesmo do peso de um átomo. Este Nome é conhecido pela lista transmitida, e o Alcorão afirma que Ele nunca é injusto com os Seus servos."),
  // 31. Al-Latif
  explain("6:103",
    en = "Al-Latif is the One who is gentle with His servants and knows the finest details of every matter. He brings good to them in ways they do not expect.",
    ar = "اللطيف هو الرفيق بعباده الخبير بدقائق الأمور. يوصل الخير إليهم من حيث لا يحتسبون.",
    bn = "আল-লাতীফ তিনি, যিনি বান্দাদের প্রতি কোমল এবং প্রতিটি বিষয়ের সূক্ষ্মতম দিক জানেন। তিনি এমনভাবে কল্যাণ পৌঁছান, যা তারা কল্পনাও করে না।",
    es = "Al-Latíf es Aquel que es amable con sus siervos y conoce los detalles más sutiles de cada asunto. Les hace llegar el bien por caminos que no esperan.",
    pt = "Al-Latif é Aquele que é gentil com os Seus servos e conhece os detalhes mais sutis de cada assunto. Faz chegar a eles o bem por caminhos que não esperam."),
  // 32. Al-Khabir
  explain("6:18",
    en = "Al-Khabir is the One who is fully aware of the inner reality of all things. Nothing about a person's condition or intention is unknown to Him.",
    ar = "الخبير هو العالم ببواطن الأمور وحقائقها. فلا تخفى عليه حال أحد ولا نيته.",
    bn = "আল-খাবীর তিনি, যিনি সবকিছুর ভেতরের বাস্তবতা পুরোপুরি জানেন। কারও অবস্থা বা নিয়ত তাঁর অজানা নয়।",
    es = "Al-Jabír es Aquel que conoce plenamente la realidad interior de todas las cosas. Nada de la condición o la intención de una persona le es desconocido.",
    pt = "Al-Khabir é Aquele que conhece plenamente a realidade interior de todas as coisas. Nada da condição ou da intenção de uma pessoa Lhe é desconhecido."),
  // 33. Al-Halim
  explain("2:235",
    en = "Al-Halim is the One who does not hasten to punish, though He sees every wrong. He gives time to return, and it is out of forbearance, not neglect.",
    ar = "الحليم هو الذي لا يعجل بالعقوبة مع قدرته عليها. يمهل عباده ليعودوا، وإمهاله حلم لا غفلة.",
    bn = "আল-হালীম তিনি, যিনি সব অন্যায় দেখেও শাস্তি দিতে তাড়াহুড়ো করেন না। তিনি ফিরে আসার সময় দেন, আর এটি তাঁর সহনশীলতা, উদাসীনতা নয়।",
    es = "Al-Halím es Aquel que no se apresura a castigar, aunque ve toda injusticia. Da tiempo para volver, y eso es indulgencia, no descuido.",
    pt = "Al-Halim é Aquele que não se apressa em castigar, embora veja toda injustiça. Dá tempo para voltar, e isso é clemência, não descuido."),
  // 34. Al-Azim
  explain("2:255",
    en = "Al-Azim is the One whose greatness is beyond what any mind can grasp. Everything else is small before Him.",
    ar = "العظيم هو ذو العظمة التي لا تحيط بها العقول. وكل شيء سواه صغير أمامه.",
    bn = "আল-আযীম তিনি, যাঁর মহত্ত্ব কোনো মন ধারণা করতে পারে না। তাঁর সামনে বাকি সবকিছুই ক্ষুদ্র।",
    es = "Al-Azím es Aquel cuya grandeza supera lo que cualquier mente puede abarcar. Todo lo demás es pequeño ante Él.",
    pt = "Al-Azim é Aquele cuja grandeza supera o que qualquer mente pode abarcar. Tudo o mais é pequeno diante d'Ele."),
  // 35. Al-Ghafur
  explain("2:173",
    en = "Al-Ghafur is the One who covers sins and pardons them. He is often named beside Ar-Rahim, as forgiveness is part of His mercy.",
    ar = "الغفور هو الذي يستر الذنوب ويتجاوز عنها. ويقترن غالبًا بالرحيم، فالمغفرة من رحمته.",
    bn = "আল-গাফূর তিনি, যিনি গুনাহ ঢেকে দেন ও মাফ করেন। প্রায়ই তাঁকে আর-রাহীমের সঙ্গে উল্লেখ করা হয়, কারণ ক্ষমা তাঁর দয়ারই অংশ।",
    es = "Al-Gafúr es Aquel que cubre los pecados y los perdona. A menudo se nombra junto a Ar-Rahím, pues el perdón forma parte de su misericordia.",
    pt = "Al-Ghafur é Aquele que cobre os pecados e os perdoa. É frequentemente nomeado junto a Ar-Rahim, pois o perdão faz parte da Sua misericórdia."),
  // 36. Ash-Shakur
  explain("35:30",
    en = "Ash-Shakur is the One who rewards a little good with much, and who appreciates what His servants do for Him. He accepts even small deeds done sincerely.",
    ar = "الشكور هو الذي يثيب على القليل من العمل بالكثير من الثواب. فيقبل العمل اليسير إذا كان خالصًا.",
    bn = "আশ-শাকূর তিনি, যিনি সামান্য সৎকর্মের বিনিময়ে অনেক প্রতিদান দেন এবং বান্দার কাজের কদর করেন। আন্তরিকতার সঙ্গে করা ছোট আমলও তিনি কবুল করেন।",
    es = "Ash-Shakúr es Aquel que recompensa un poco de bien con mucho y valora lo que sus siervos hacen por Él. Acepta incluso las obras pequeñas hechas con sinceridad.",
    pt = "Ash-Shakur é Aquele que recompensa um pouco de bem com muito e valoriza o que os Seus servos fazem por Ele. Aceita até as obras pequenas feitas com sinceridade."),
  // 37. Al-Ali
  explain("2:255",
    en = "Al-Ali is the One who is above all things, in His essence, His power and His rank. Nothing stands higher than Him.",
    ar = "العلي هو الذي علا فوق كل شيء بذاته وقدره وقهره. فلا شيء أعلى منه.",
    bn = "আল-আলী তিনি, যিনি সবকিছুর উপরে, সত্তা, ক্ষমতা ও মর্যাদায়। তাঁর চেয়ে উঁচু কিছুই নেই।",
    es = "Al-Alí es Aquel que está por encima de todo, en su esencia, su poder y su rango. Nada está más alto que Él.",
    pt = "Al-Ali é Aquele que está acima de tudo, em Sua essência, Seu poder e Seu grau. Nada está mais alto que Ele."),
  // 38. Al-Kabir
  explain("22:62",
    en = "Al-Kabir is the One who is the greatest, and whose greatness has no limit. It is often named with Al-Ali, the Most High.",
    ar = "الكبير هو ذو الكبرياء التي لا حد لها. ويقترن في القرآن غالبًا باسم العلي.",
    bn = "আল-কাবীর তিনি, যিনি সর্বমহান, যাঁর মহত্ত্বের কোনো সীমা নেই। কুরআনে এটি প্রায়ই আল-আলীর সঙ্গে এসেছে।",
    es = "Al-Kabír es Aquel que es el más grande, y cuya grandeza no tiene límite. A menudo se nombra junto a Al-Alí, el Altísimo.",
    pt = "Al-Kabir é Aquele que é o maior, e cuja grandeza não tem limite. É frequentemente nomeado junto a Al-Ali, o Altíssimo."),
  // 39. Al-Hafiz
  explain("11:57",
    en = "Al-Hafiz is the One who preserves everything He created, from the heavens to the deeds of people. He is the best protector for those who trust in Him.",
    ar = "الحفيظ هو الذي يحفظ كل ما خلق، من السماوات إلى أعمال الناس. وهو خير حافظ لمن توكل عليه.",
    bn = "আল-হাফীয তিনি, যিনি তাঁর সৃষ্ট সবকিছু সংরক্ষণ করেন, আসমান থেকে মানুষের আমল পর্যন্ত। যারা তাঁর ওপর ভরসা করে, তাদের জন্য তিনিই সর্বোত্তম রক্ষক।",
    es = "Al-Hafíz es Aquel que preserva todo lo que creó, desde los cielos hasta las obras de las personas. Es el mejor protector para quienes confían en Él.",
    pt = "Al-Hafiz é Aquele que preserva tudo o que criou, dos céus às obras das pessoas. É o melhor protetor para quem confia n'Ele."),
  // 40. Al-Muqit
  explain("4:85",
    en = "Al-Muqit is the One who gives every creature the sustenance it needs. He is also able to keep watch over and account for all things.",
    ar = "المقيت هو الذي يعطي كل مخلوق ما يقتات به. وهو القادر على كل شيء والحافظ له.",
    bn = "আল-মুকীত তিনি, যিনি প্রতিটি সৃষ্টিকে তার প্রয়োজনীয় খাদ্য ও জীবিকা দেন। তিনি সবকিছুর ওপর ক্ষমতাবান ও তত্ত্বাবধায়কও।",
    es = "Al-Muqít es Aquel que da a cada criatura el alimento que necesita. También es capaz de velar sobre todas las cosas y de pedirles cuentas.",
    pt = "Al-Muqit é Aquele que dá a cada criatura o alimento de que precisa. Também é capaz de zelar por todas as coisas e de lhes pedir contas."),
  // 41. Al-Hasib
  explain("4:6",
    en = "Al-Hasib is the One who suffices His servants, and who takes full account of what they do. It is enough to have Him as the Reckoner.",
    ar = "الحسيب هو الكافي لعباده، والمحاسب لهم على أعمالهم. وكفى به حسيبًا.",
    bn = "আল-হাসীব তিনি, যিনি বান্দাদের জন্য যথেষ্ট এবং তাদের আমলের পূর্ণ হিসাব নেন। হিসাব গ্রহণকারী হিসেবে তিনিই যথেষ্ট।",
    es = "Al-Hasíb es Aquel que basta a sus siervos y que toma plena cuenta de lo que hacen. Basta con tenerle a Él como quien toma cuentas.",
    pt = "Al-Hasib é Aquele que basta aos Seus servos e que toma plena conta do que fazem. Basta tê-Lo como Aquele que presta contas."),
  // 42. Al-Jalil
  explain("55:27",
    en = "Al-Jalil is the One who possesses majesty and grandeur in every attribute. The Qur'an speaks of Him as the Lord of Majesty and Honor.",
    ar = "الجليل هو صاحب العظمة والجلال في كل صفاته. وقد وصفه القرآن بأنه ذو الجلال والإكرام.",
    bn = "আল-জালীল তিনি, যিনি সব গুণে মহিমা ও গাম্ভীর্যের অধিকারী। কুরআন তাঁকে মহিমা ও সম্মানের অধিকারী বলে বর্ণনা করেছে।",
    es = "Al-Yalíl es Aquel que posee majestad y grandeza en todos sus atributos. El Corán habla de Él como el Señor de la Majestad y la Generosidad.",
    pt = "Al-Jalil é Aquele que possui majestade e grandeza em todos os Seus atributos. O Alcorão fala d'Ele como o Senhor da Majestade e da Generosidade."),
  // 43. Al-Karim
  explain("82:6",
    en = "Al-Karim is the One who is generous, giving without being asked and forgiving without grudge. His generosity is far beyond what anyone deserves.",
    ar = "الكريم هو كثير الخير والعطاء، يعطي قبل السؤال ويعفو بلا مَنّ. وكرمه فوق ما يستحقه أحد.",
    bn = "আল-কারীম তিনি, যিনি দানশীল, চাওয়ার আগেই দেন এবং কোনো খোঁটা ছাড়াই ক্ষমা করেন। তাঁর দান কারও প্রাপ্যের চেয়ে অনেক বেশি।",
    es = "Al-Karím es Aquel que es generoso, que da sin que se le pida y perdona sin reproche. Su generosidad supera con mucho lo que alguien merece.",
    pt = "Al-Karim é Aquele que é generoso, que dá sem que se peça e perdoa sem reprovação. A Sua generosidade supera em muito o que alguém merece."),
  // 44. Ar-Raqib
  explain("4:1",
    en = "Ar-Raqib is the One who watches over everything at every moment. Nothing is done without Him observing it.",
    ar = "الرقيب هو الذي يراقب كل شيء في كل لحظة. فلا يجري شيء إلا وهو مطلع عليه.",
    bn = "আর-রাকীব তিনি, যিনি প্রতিটি মুহূর্তে সবকিছুর ওপর নজর রাখেন। তাঁর দৃষ্টির বাইরে কিছুই ঘটে না।",
    es = "Ar-Raqíb es Aquel que vigila todo en cada instante. Nada sucede sin que Él lo observe.",
    pt = "Ar-Raqib é Aquele que vigia tudo a cada instante. Nada acontece sem que Ele o observe."),
  // 45. Al-Mujib
  explain("11:61",
    en = "Al-Mujib is the One who answers those who call on Him. He is near, and no sincere prayer goes unheard.",
    ar = "المجيب هو الذي يجيب من دعاه. وهو قريب، ولا يضيع عنده دعاء صادق.",
    bn = "আল-মুজীব তিনি, যিনি তাঁকে ডাকা মানুষের ডাকে সাড়া দেন। তিনি নিকটে আছেন, আর আন্তরিক দোয়া তাঁর কাছে বৃথা যায় না।",
    es = "Al-Muyíb es Aquel que responde a quienes le invocan. Está cerca, y ninguna súplica sincera queda sin ser oída.",
    pt = "Al-Mujib é Aquele que responde a quem O invoca. Está perto, e nenhuma súplica sincera fica sem ser ouvida."),
  // 46. Al-Wasi'
  explain("2:115",
    en = "Al-Wasi' is the One whose mercy, knowledge and bounty are all-encompassing. He is never limited by place, time or by the number of those who ask.",
    ar = "الواسع هو الذي وسعت رحمته وعلمه وفضله كل شيء. فلا يحده مكان ولا زمان ولا كثرة السائلين.",
    bn = "আল-ওয়াসি' তিনি, যাঁর দয়া, জ্ঞান ও দান সবকিছুকে ঘিরে আছে। স্থান, কাল বা প্রার্থীর সংখ্যা তাঁকে সীমাবদ্ধ করতে পারে না।",
    es = "Al-Wási' es Aquel cuya misericordia, conocimiento y generosidad lo abarcan todo. No lo limitan el lugar, el tiempo ni el número de quienes piden.",
    pt = "Al-Wasi' é Aquele cuja misericórdia, conhecimento e generosidade abrangem tudo. Não O limitam o lugar, o tempo nem o número dos que pedem."),
  // 47. Al-Hakim
  explain("2:32",
    en = "Al-Hakim is the One who puts every matter in its proper place, with perfect wisdom. Nothing He decrees is without purpose.",
    ar = "الحكيم هو الذي يضع كل أمر في موضعه بحكمة كاملة. فلا شيء مما يقضيه بلا غاية.",
    bn = "আল-হাকীম তিনি, যিনি পূর্ণ প্রজ্ঞায় প্রতিটি বিষয় তার যথাস্থানে রাখেন। তাঁর কোনো সিদ্ধান্তই উদ্দেশ্যহীন নয়।",
    es = "Al-Hakím es Aquel que pone cada asunto en su lugar, con sabiduría perfecta. Nada de lo que decreta carece de propósito.",
    pt = "Al-Hakim é Aquele que coloca cada assunto em seu lugar, com sabedoria perfeita. Nada do que decreta é sem propósito."),
  // 48. Al-Wadud
  explain("85:14",
    en = "Al-Wadud is the One who loves His righteous servants and is loved by them. It is a love that comes with forgiveness, and the Qur'an names it right after Al-Ghafur.",
    ar = "الودود هو الذي يحب عباده الصالحين ويحبونه. وهو حب مقرون بالمغفرة، وقد جاء في القرآن بعد الغفور مباشرة.",
    bn = "আল-ওয়াদূদ তিনি, যিনি তাঁর নেক বান্দাদের ভালোবাসেন এবং তারাও তাঁকে ভালোবাসে। এই ভালোবাসা ক্ষমার সঙ্গে যুক্ত, আর কুরআনে এটি আল-গাফূরের ঠিক পরেই এসেছে।",
    es = "Al-Wadúd es Aquel que ama a sus siervos justos y es amado por ellos. Es un amor que va unido al perdón, y el Corán lo nombra justo después de Al-Gafúr.",
    pt = "Al-Wadud é Aquele que ama os Seus servos justos e é amado por eles. É um amor que vem junto com o perdão, e o Alcorão o nomeia logo depois de Al-Ghafur."),
  // 49. Al-Majid
  explain("11:73",
    en = "Al-Majid is the One of boundless glory and honor, whose excellence is exalted. The Qur'an names Him Al-Hamid, the Praiseworthy, together with it.",
    ar = "المجيد هو ذو المجد والشرف الواسع، المتعالي في كماله. وقد قرنه القرآن باسم الحميد.",
    bn = "আল-মাজীদ তিনি, যাঁর গৌরব ও মর্যাদা অসীম এবং যাঁর পূর্ণতা সুউচ্চ। কুরআনে এটি আল-হামীদের সঙ্গে এসেছে।",
    es = "Al-Mayíd es Aquel de gloria y honor ilimitados, cuya excelencia es sublime. El Corán lo nombra junto a Al-Hamíd, el Digno de Alabanza.",
    pt = "Al-Majid é Aquele de glória e honra ilimitadas, cuja excelência é sublime. O Alcorão o nomeia junto a Al-Hamid, o Digno de Louvor."),
  // 50. Al-Ba'ith
  explain("22:7",
    en = "Al-Ba'ith is the One who will raise all of creation from the dead on the Day of Judgment. He also sends the messengers to guide mankind.",
    ar = "الباعث هو الذي يبعث الخلق من القبور يوم القيامة. وهو الذي يبعث الرسل لهداية الناس.",
    bn = "আল-বা'ইস তিনি, যিনি কিয়ামতের দিন সব সৃষ্টিকে কবর থেকে পুনরুত্থিত করবেন। তিনিই মানুষের হিদায়াতের জন্য রাসূল পাঠান।",
    es = "Al-Bá'iz es Aquel que resucitará a toda la creación de entre los muertos el Día del Juicio. También es quien envía a los mensajeros para guiar a la humanidad.",
    pt = "Al-Ba'ith é Aquele que ressuscitará toda a criação dentre os mortos no Dia do Julgamento. Também é quem envia os mensageiros para guiar a humanidade."),
  // 51. Ash-Shahid
  explain("5:117",
    en = "Ash-Shahid is the One who witnesses everything and is never absent from any event. On the Day of Judgment He will be the witness over all.",
    ar = "الشهيد هو الذي يشهد كل شيء ولا يغيب عن أمر. وسيكون يوم القيامة شاهدًا على الجميع.",
    bn = "আশ-শাহীদ তিনি, যিনি সবকিছুর সাক্ষী এবং কোনো ঘটনা থেকে অনুপস্থিত থাকেন না। কিয়ামতের দিন তিনিই সবার ওপর সাক্ষী হবেন।",
    es = "Ash-Shahíd es Aquel que presencia todo y nunca está ausente de ningún suceso. El Día del Juicio será testigo sobre todos.",
    pt = "Ash-Shahid é Aquele que presencia tudo e nunca está ausente de nenhum acontecimento. No Dia do Julgamento será testemunha sobre todos."),
  // 52. Al-Haqq
  explain("22:6",
    en = "Al-Haqq is the One who is the ultimate Truth, whose existence is certain and whose promise is sure. Whatever is called upon besides Him is false.",
    ar = "الحق هو الثابت وجوده الذي لا شك فيه، ووعده حق. وكل ما يُدعى من دونه باطل.",
    bn = "আল-হাক্ক তিনি, যিনি পরম সত্য, যাঁর অস্তিত্ব নিশ্চিত এবং যাঁর প্রতিশ্রুতি অবশ্যম্ভাবী। তাঁকে ছাড়া যাকে ডাকা হয়, সবই অসার।",
    es = "Al-Haqq es Aquel que es la Verdad última, cuya existencia es cierta y cuya promesa es segura. Todo lo que se invoca fuera de Él es falso.",
    pt = "Al-Haqq é Aquele que é a Verdade suprema, cuja existência é certa e cuja promessa é segura. Tudo o que se invoca além d'Ele é falso."),
  // 53. Al-Wakil
  explain("3:173",
    en = "Al-Wakil is the One to whom affairs are entrusted, and who is enough for whoever relies on Him. The believers say that He is the best Disposer of affairs.",
    ar = "الوكيل هو الذي تُفوَّض إليه الأمور، ويكفي من توكل عليه. ويقول المؤمنون إنه نعم الوكيل.",
    bn = "আল-ওয়াকীল তিনি, যাঁর ওপর সব বিষয় ন্যস্ত করা হয় এবং যিনি ভরসাকারীর জন্য যথেষ্ট। মুমিনরা বলে, তিনিই সর্বোত্তম কর্মবিধায়ক।",
    es = "Al-Wakíl es Aquel a quien se confían los asuntos, y que basta a quien se apoya en Él. Los creyentes dicen que es el mejor Garante.",
    pt = "Al-Wakil é Aquele a quem se confiam os assuntos, e que basta a quem se apoia n'Ele. Os crentes dizem que Ele é o melhor Procurador."),
  // 54. Al-Qawi
  explain("22:40",
    en = "Al-Qawi is the One whose strength is complete and never tires or weakens. The Qur'an often pairs it with Al-Aziz, the Almighty.",
    ar = "القوي هو ذو القوة الكاملة التي لا تضعف ولا تتعب. ويقترن في القرآن غالبًا بالعزيز.",
    bn = "আল-কাওয়িয়্য তিনি, যাঁর শক্তি পূর্ণ এবং কখনো ক্লান্ত বা দুর্বল হয় না। কুরআনে এটি প্রায়ই আল-আযীযের সঙ্গে এসেছে।",
    es = "Al-Qawí es Aquel cuya fuerza es completa y nunca se cansa ni se debilita. El Corán lo une a menudo con Al-Azíz, el Poderoso.",
    pt = "Al-Qawi é Aquele cuja força é completa e nunca se cansa nem enfraquece. O Alcorão frequentemente o une a Al-Aziz, o Poderoso."),
  // 55. Al-Matin
  explain("51:58",
    en = "Al-Matin is the One who is firm in strength, with no weakness ever touching Him. It appears in the verse that names Him as the Provider.",
    ar = "المتين هو الشديد القوة الذي لا يمسه ضعف. وقد ورد في الآية التي ذكر فيها أنه الرزاق.",
    bn = "আল-মাতীন তিনি, যিনি শক্তিতে অতি দৃঢ় এবং যাঁকে কখনো দুর্বলতা স্পর্শ করে না। যে আয়াতে তাঁকে রিযিকদাতা বলা হয়েছে, সেখানেই এই নাম এসেছে।",
    es = "Al-Matín es Aquel que es firme en su fuerza, sin que ninguna debilidad le toque jamás. Aparece en el versículo que lo nombra como el Proveedor.",
    pt = "Al-Matin é Aquele que é firme em Sua força, sem que nenhuma fraqueza O toque jamais. Aparece no versículo que O nomeia como o Provedor."),
  // 56. Al-Wali
  explain("2:257",
    en = "Al-Wali is the Protecting Friend of the believers. He takes them out of darkness into light and looks after their affairs.",
    ar = "الولي هو ناصر المؤمنين ومتولي أمورهم. يخرجهم من الظلمات إلى النور.",
    bn = "আল-ওয়ালী মুমিনদের অভিভাবক ও বন্ধু। তিনি তাদের অন্ধকার থেকে আলোর দিকে বের করে আনেন এবং তাদের বিষয়গুলো দেখাশোনা করেন।",
    es = "Al-Walí es el Amigo protector de los creyentes. Los saca de las tinieblas hacia la luz y se ocupa de sus asuntos.",
    pt = "Al-Wali é o Amigo protetor dos crentes. Tira-os das trevas para a luz e cuida dos seus assuntos."),
  // 57. Al-Hamid
  explain("14:8",
    en = "Al-Hamid is the One who deserves praise in every circumstance, for His perfection and His favors. He is worthy of praise whether people thank Him or not.",
    ar = "الحميد هو المستحق للحمد في كل حال، لكماله ونعمه. وهو محمود سواء شكره الناس أم لم يشكروه.",
    bn = "আল-হামীদ তিনি, যিনি সর্বাবস্থায় প্রশংসার যোগ্য, তাঁর পূর্ণতা ও নিয়ামতের কারণে। মানুষ কৃতজ্ঞতা জানাক বা না জানাক, তিনি প্রশংসিতই।",
    es = "Al-Hamíd es Aquel que merece alabanza en toda circunstancia, por su perfección y sus favores. Es digno de alabanza, le den gracias o no.",
    pt = "Al-Hamid é Aquele que merece louvor em toda circunstância, por Sua perfeição e Seus favores. É digno de louvor, quer Lhe agradeçam ou não."),
  // 58. Al-Muhsi
  explain("72:28",
    en = "Al-Muhsi is the One who has counted everything exactly, down to the last number. No deed, however small, is missing from His record.",
    ar = "المحصي هو الذي أحصى كل شيء عددًا بدقة. فلا يغيب عن إحصائه عمل مهما صغر.",
    bn = "আল-মুহসী তিনি, যিনি সবকিছু নিখুঁতভাবে গুনে রেখেছেন, শেষ সংখ্যা পর্যন্ত। কোনো আমল, যত ছোটই হোক, তাঁর হিসাব থেকে বাদ যায় না।",
    es = "Al-Muhsí es Aquel que ha contado todo con exactitud, hasta el último número. Ninguna obra, por pequeña que sea, falta en su registro.",
    pt = "Al-Muhsi é Aquele que contou tudo com exatidão, até o último número. Nenhuma obra, por menor que seja, falta no Seu registro."),
  // 59. Al-Mubdi'
  explain("85:13",
    en = "Al-Mubdi' is the One who began creation without any model before it. He is the one who originates, and He is named together with Al-Mu'id.",
    ar = "المبدئ هو الذي بدأ الخلق على غير مثال سابق. فهو الذي يبدأ، ويُذكر مع المعيد.",
    bn = "আল-মুবদি' তিনি, যিনি আগের কোনো নমুনা ছাড়াই সৃষ্টির সূচনা করেছেন। তিনিই সূচনাকারী, আর এই নাম আল-মু'ঈদের সঙ্গে বলা হয়।",
    es = "Al-Mubdi' es Aquel que inició la creación sin ningún modelo anterior. Él es quien da comienzo, y se nombra junto a Al-Mu'íd.",
    pt = "Al-Mubdi' é Aquele que iniciou a criação sem nenhum modelo anterior. Ele é quem dá começo, e é nomeado junto a Al-Mu'id."),
  // 60. Al-Mu'id
  explain("85:13",
    en = "Al-Mu'id is the One who brings creation back after it perishes. The One who began it the first time is able to restore it.",
    ar = "المعيد هو الذي يعيد الخلق بعد فنائه. فمن بدأه أول مرة قادر على إعادته.",
    bn = "আল-মু'ঈদ তিনি, যিনি ধ্বংসের পর সৃষ্টিকে ফিরিয়ে আনেন। যিনি প্রথমবার সৃষ্টি করেছেন, তিনিই তা পুনরায় ফিরিয়ে দিতে সক্ষম।",
    es = "Al-Mu'íd es Aquel que devuelve la creación a la vida después de que perece. Quien la inició la primera vez es capaz de restaurarla.",
    pt = "Al-Mu'id é Aquele que traz a criação de volta depois que perece. Quem a iniciou na primeira vez é capaz de restaurá-la."),
  // 61. Al-Muhyi
  explain("30:50",
    en = "Al-Muhyi is the One who gives life, from the womb to the earth after it has been dry. The Qur'an offers this as a sign that He can give life to the dead.",
    ar = "المحيي هو الذي يهب الحياة، من الأرحام إلى الأرض بعد يباسها. وقد جعله القرآن دليلًا على إحياء الموتى.",
    bn = "আল-মুহয়ী তিনি, যিনি জীবন দান করেন, গর্ভে প্রাণ থেকে শুকনো জমিকে সজীব করা পর্যন্ত। কুরআন একে মৃতদের জীবিত করার ক্ষমতার নিদর্শন হিসেবে তুলে ধরেছে।",
    es = "Al-Muhyí es Aquel que da la vida, desde el vientre hasta la tierra después de haber estado seca. El Corán lo presenta como señal de que puede dar vida a los muertos.",
    pt = "Al-Muhyi é Aquele que dá a vida, do ventre à terra depois de ter estado seca. O Alcorão o apresenta como sinal de que Ele pode dar vida aos mortos."),
  // 62. Al-Mumit
  explain("2:258",
    en = "Al-Mumit is the One who decrees death for every living thing, at the time He has set. Life and death are both in His hands.",
    ar = "المميت هو الذي يقدّر الموت على كل حي في الأجل الذي حدده. فالحياة والموت كلاهما بيده.",
    bn = "আল-মুমীত তিনি, যিনি প্রতিটি প্রাণীর জন্য তাঁর নির্ধারিত সময়ে মৃত্যু নির্ধারণ করেন। জীবন ও মৃত্যু দুটোই তাঁর হাতে।",
    es = "Al-Mumít es Aquel que decreta la muerte de todo ser vivo, en el momento que Él ha fijado. La vida y la muerte están ambas en su mano.",
    pt = "Al-Mumit é Aquele que decreta a morte de todo ser vivo, no momento que Ele fixou. A vida e a morte estão ambas em Suas mãos."),
  // 63. Al-Hayy
  explain("2:255",
    en = "Al-Hayy is the One whose life is perfect, with no beginning and no end. All other life depends on His.",
    ar = "الحي هو ذو الحياة الكاملة التي لا بداية لها ولا نهاية. وكل حياة سواها معتمدة عليها.",
    bn = "আল-হাইয়্য তিনি, যাঁর জীবন পূর্ণ, যার শুরু বা শেষ নেই। অন্য সব জীবন তাঁর জীবনের ওপর নির্ভরশীল।",
    es = "Al-Hayy es Aquel cuya vida es perfecta, sin principio ni fin. Toda otra vida depende de la suya.",
    pt = "Al-Hayy é Aquele cuja vida é perfeita, sem princípio nem fim. Toda outra vida depende da Sua."),
  // 64. Al-Qayyum
  explain("2:255",
    en = "Al-Qayyum is the One who stands by Himself and keeps everything else standing. Creation needs Him at every moment, and He needs nothing.",
    ar = "القيوم هو القائم بنفسه المقيم لغيره. فالخلق محتاج إليه في كل لحظة، وهو غني عن كل شيء.",
    bn = "আল-কাইয়্যূম তিনি, যিনি নিজে প্রতিষ্ঠিত এবং অন্য সবকিছুকে ধরে রাখেন। সৃষ্টি প্রতি মুহূর্তে তাঁর মুখাপেক্ষী, আর তিনি কারও মুখাপেক্ষী নন।",
    es = "Al-Qayyúm es Aquel que se sostiene por Sí mismo y sostiene todo lo demás. La creación lo necesita en cada instante, y Él no necesita nada.",
    pt = "Al-Qayyum é Aquele que subsiste por Si mesmo e sustenta tudo o mais. A criação precisa d'Ele a cada instante, e Ele não precisa de nada."),
  // 65. Al-Wajid
  explain(null,
    en = "Al-Wajid is the One who lacks nothing and who finds whatever He wants, and nothing He seeks escapes Him. This Name is known from the transmitted list of the Names.",
    ar = "الواجد هو الذي لا يعوزه شيء ولا يفوته ما يريد. والاسم معروف من القائمة المروية للأسماء.",
    bn = "আল-ওয়াজিদ তিনি, যাঁর কোনো কিছুর অভাব নেই এবং যা চান তা-ই পান। এই নাম বর্ণিত তালিকা থেকে জানা যায়।",
    es = "Al-Wáyid es Aquel que no carece de nada y que halla todo lo que quiere, sin que nada de lo que busca se le escape. Este Nombre se conoce por la lista transmitida.",
    pt = "Al-Wajid é Aquele que não carece de nada e que encontra tudo o que quer, sem que nada do que busca Lhe escape. Este Nome é conhecido pela lista transmitida."),
  // 66. Al-Majid
  explain(null,
    en = "Al-Majid, in this form, describes the One who is perfect in nobility and generosity. It comes from the same root as Al-Majid in the Qur'an, and is known from the transmitted list.",
    ar = "الماجد هو الكامل في شرفه وكرمه. وهو من جذر المجيد الوارد في القرآن، ويُعرف من القائمة المروية.",
    bn = "আল-মাজিদ এই রূপে তাঁকে বোঝায়, যিনি মর্যাদা ও দানশীলতায় পরিপূর্ণ। এটি কুরআনে আসা আল-মাজীদের একই মূল থেকে, আর বর্ণিত তালিকা থেকে জানা যায়।",
    es = "Al-Máyid, en esta forma, describe a Aquel que es perfecto en nobleza y generosidad. Viene de la misma raíz que Al-Mayíd del Corán, y se conoce por la lista transmitida.",
    pt = "Al-Majid, nesta forma, descreve Aquele que é perfeito em nobreza e generosidade. Vem da mesma raiz que Al-Majid do Alcorão, e é conhecido pela lista transmitida."),
  // 67. Al-Wahid
  explain("13:16",
    en = "Al-Wahid is the One who is unique in His essence and attributes, with no partner or equal. This is the heart of tawhid.",
    ar = "الواحد هو المتفرد في ذاته وصفاته، لا شريك له ولا مثيل. وهذا لب التوحيد.",
    bn = "আল-ওয়াহিদ তিনি, যিনি সত্তা ও গুণে অদ্বিতীয়, যাঁর কোনো শরিক বা সমকক্ষ নেই। এটিই তাওহীদের মূল কথা।",
    es = "Al-Wáhid es Aquel que es único en su esencia y sus atributos, sin asociado ni igual. Este es el corazón del tawhid.",
    pt = "Al-Wahid é Aquele que é único em Sua essência e Seus atributos, sem associado nem igual. Este é o coração do tawhid."),
  // 68. As-Samad
  explain("112:2",
    en = "As-Samad is the One to whom all creatures turn in their needs, while He needs no one. The whole of Surat al-Ikhlas speaks of Him.",
    ar = "الصمد هو الذي يُقصد في الحوائج، ولا يحتاج إلى أحد. وسورة الإخلاص كلها في وصفه.",
    bn = "আস-সামাদ তিনি, যাঁর কাছে সব সৃষ্টি নিজেদের প্রয়োজনে ফেরে, অথচ তিনি কারও মুখাপেক্ষী নন। সূরা ইখলাসের পুরোটাই তাঁর বর্ণনা।",
    es = "As-Samad es Aquel a quien acuden todas las criaturas en sus necesidades, mientras que Él no necesita a nadie. Toda la sura Al-Ijlás habla de Él.",
    pt = "As-Samad é Aquele a quem todas as criaturas recorrem em suas necessidades, enquanto Ele não precisa de ninguém. Toda a sura Al-Ikhlas fala d'Ele."),
  // 69. Al-Qadir
  explain("6:65",
    en = "Al-Qadir is the One who is able to do all things, and nothing is beyond Him. His ability has no limit.",
    ar = "القادر هو الذي يقدر على كل شيء ولا يعجزه شيء. وقدرته لا حد لها.",
    bn = "আল-কাদির তিনি, যিনি সবকিছু করতে সক্ষম এবং কিছুই তাঁকে অক্ষম করতে পারে না। তাঁর ক্ষমতার কোনো সীমা নেই।",
    es = "Al-Qádir es Aquel que es capaz de hacer todas las cosas, y nada está fuera de su alcance. Su capacidad no tiene límite.",
    pt = "Al-Qadir é Aquele que é capaz de fazer todas as coisas, e nada está fora do Seu alcance. A Sua capacidade não tem limite."),
  // 70. Al-Muqtadir
  explain("18:45",
    en = "Al-Muqtadir is the One whose power is complete and takes hold of whatever He wishes. When He decides a matter, nothing can stand against it.",
    ar = "المقتدر هو التام القدرة الذي يمسك بما يشاء. فإذا قضى أمرًا لم يقف أمامه شيء.",
    bn = "আল-মুকতাদির তিনি, যাঁর ক্ষমতা পূর্ণ এবং যা চান তা ধরে ফেলেন। তিনি কোনো বিষয় স্থির করলে কিছুই তা ঠেকাতে পারে না।",
    es = "Al-Muqtadir es Aquel cuyo poder es completo y alcanza todo lo que desea. Cuando decide un asunto, nada puede oponérsele.",
    pt = "Al-Muqtadir é Aquele cujo poder é completo e alcança tudo o que deseja. Quando decide um assunto, nada pode se opor."),
  // 71. Al-Muqaddim
  explain(null,
    en = "Al-Muqaddim is the One who brings forward whom He wills, in rank, in time or in favor. It is known from the transmitted list, and is the counterpart of Al-Mu'akhkhir.",
    ar = "المقدّم هو الذي يقدّم من يشاء في الرتبة أو الزمان أو الفضل. والاسم معروف من القائمة المروية، وهو مقابل المؤخّر.",
    bn = "আল-মুকাদ্দিম তিনি, যিনি যাকে ইচ্ছা মর্যাদা, সময় বা অনুগ্রহে এগিয়ে দেন। নামটি বর্ণিত তালিকা থেকে জানা যায়, আর এটি আল-মুআখখিরের বিপরীত।",
    es = "Al-Muqaddim es Aquel que adelanta a quien quiere, en rango, en tiempo o en favor. Se conoce por la lista transmitida, y es el contrapunto de Al-Mu'ajjir.",
    pt = "Al-Muqaddim é Aquele que adianta a quem quer, em grau, em tempo ou em favor. É conhecido pela lista transmitida, e é o contraponto de Al-Mu'akhkhir."),
  // 72. Al-Mu'akhkhir
  explain("14:42",
    en = "Al-Mu'akhkhir is the One who delays whom He wills, such as the wrongdoers, whom He gives time. Nothing is put off or brought forward except by His decree.",
    ar = "المؤخّر هو الذي يؤخّر من يشاء، كالظالمين الذين يمهلهم. فلا يتقدم شيء ولا يتأخر إلا بقضائه.",
    bn = "আল-মুআখখির তিনি, যিনি যাকে ইচ্ছা পিছিয়ে দেন, যেমন জালিমদের অবকাশ দেন। তাঁর ফয়সালা ছাড়া কিছুই এগোয় না, পিছোয়ও না।",
    es = "Al-Mu'ajjir es Aquel que retrasa a quien quiere, como a los injustos, a quienes concede un plazo. Nada se adelanta ni se retrasa salvo por su decreto.",
    pt = "Al-Mu'akhkhir é Aquele que atrasa a quem quer, como os injustos, a quem concede um prazo. Nada se adianta nem se atrasa senão por Seu decreto."),
  // 73. Al-Awwal
  explain("57:3",
    en = "Al-Awwal is the One who is First, and before whom there was nothing. Everything else has a beginning, and He has none.",
    ar = "الأول هو الذي ليس قبله شيء. وكل ما سواه له بداية، وهو لا بداية له.",
    bn = "আল-আউয়াল তিনি, যিনি প্রথম, যাঁর আগে কিছুই ছিল না। বাকি সবকিছুর শুরু আছে, তাঁর নেই।",
    es = "Al-Awwal es Aquel que es el Primero, antes del cual no había nada. Todo lo demás tiene un comienzo, y Él no lo tiene.",
    pt = "Al-Awwal é Aquele que é o Primeiro, antes do qual não havia nada. Tudo o mais tem um começo, e Ele não tem."),
  // 74. Al-Akhir
  explain("57:3",
    en = "Al-Akhir is the One who is Last, and after whom there will be nothing. All things pass away, and He remains.",
    ar = "الآخر هو الذي ليس بعده شيء. فكل شيء يفنى ويبقى هو.",
    bn = "আল-আখির তিনি, যিনি সর্বশেষ, যাঁর পরে কিছুই থাকবে না। সবকিছু ধ্বংস হয়, আর তিনি থেকে যান।",
    es = "Al-Ájir es Aquel que es el Último, después del cual no habrá nada. Todas las cosas pasan, y Él permanece.",
    pt = "Al-Akhir é Aquele que é o Último, depois do qual não haverá nada. Todas as coisas passam, e Ele permanece."),
  // 75. Az-Zahir
  explain("57:3",
    en = "Az-Zahir is the One who is Manifest, above all things, so that nothing stands over Him. His signs are visible in everything created.",
    ar = "الظاهر هو الذي ليس فوقه شيء. وآياته ظاهرة في كل مخلوق.",
    bn = "আয-যাহির তিনি, যিনি প্রকাশ্য ও সবকিছুর ঊর্ধ্বে, তাঁর ওপরে কিছুই নেই। প্রতিটি সৃষ্টিতে তাঁর নিদর্শন দৃশ্যমান।",
    es = "Az-Záhir es Aquel que es el Manifiesto, por encima de todo, de modo que nada está sobre Él. Sus señales son visibles en todo lo creado.",
    pt = "Az-Zahir é Aquele que é o Manifesto, acima de tudo, de modo que nada está sobre Ele. Os Seus sinais são visíveis em tudo o que foi criado."),
  // 76. Al-Batin
  explain("57:3",
    en = "Al-Batin is the One who is Hidden, closer than anything, so that nothing is nearer than Him. He knows every secret within the heart.",
    ar = "الباطن هو الذي ليس دونه شيء، وهو أقرب من كل قريب. يعلم كل ما في الصدور.",
    bn = "আল-বাতিন তিনি, যিনি অপ্রকাশ্য ও সবকিছুর চেয়ে নিকটে, তাঁর চেয়ে কাছে কিছুই নেই। অন্তরের প্রতিটি গোপন কথা তিনি জানেন।",
    es = "Al-Bátin es Aquel que es el Oculto, más cercano que cualquier cosa, de modo que nada está más próximo que Él. Conoce todo secreto del corazón.",
    pt = "Al-Batin é Aquele que é o Oculto, mais próximo que qualquer coisa, de modo que nada está mais perto que Ele. Conhece todo segredo do coração."),
  // 77. Al-Wali
  explain("13:11",
    en = "Al-Wali, as the Governor, is the One who manages the affairs of His creation. The Qur'an says that apart from Him, people have no governor.",
    ar = "الوالي هو الذي يتولى أمر خلقه ويدبره. وقد بيّن القرآن أنه لا والي لهم من دونه.",
    bn = "আল-ওয়ালী, শাসনকর্তা হিসেবে, তিনি যিনি তাঁর সৃষ্টির সব বিষয় পরিচালনা করেন। কুরআন বলে, তাঁকে ছাড়া মানুষের কোনো শাসনকর্তা নেই।",
    es = "Al-Wáli, como Gobernante, es Aquel que administra los asuntos de su creación. El Corán dice que, fuera de Él, la gente no tiene gobernante.",
    pt = "Al-Wali, como Governante, é Aquele que administra os assuntos da Sua criação. O Alcorão diz que, além d'Ele, as pessoas não têm governante."),
  // 78. Al-Muta'ali
  explain("13:9",
    en = "Al-Muta'ali is the One who is exalted above everything He has created. He is high above any likeness to His creatures.",
    ar = "المتعالي هو الذي علا فوق كل ما خلق. فهو منزه عن مشابهة المخلوقين.",
    bn = "আল-মুতা'আলী তিনি, যিনি তাঁর সৃষ্ট সবকিছুর ঊর্ধ্বে সমুন্নত। সৃষ্টির সঙ্গে কোনো সাদৃশ্য থেকে তিনি বহু ঊর্ধ্বে।",
    es = "Al-Muta'ál es Aquel que está exaltado por encima de todo lo que creó. Está muy por encima de toda semejanza con sus criaturas.",
    pt = "Al-Muta'ali é Aquele que está exaltado acima de tudo o que criou. Está muito acima de qualquer semelhança com as Suas criaturas."),
  // 79. Al-Barr
  explain("52:28",
    en = "Al-Barr is the One who is endlessly good and kind to His servants. The Qur'an names Him Al-Barr with Ar-Rahim, in a verse of the people of Paradise.",
    ar = "البر هو كثير الإحسان واللطف بعباده. وقد جاء مع الرحيم على لسان أهل الجنة.",
    bn = "আল-বার্র তিনি, যিনি বান্দাদের প্রতি অফুরন্ত কল্যাণকারী ও দয়ালু। জান্নাতবাসীদের কথায় কুরআনে এটি আর-রাহীমের সঙ্গে এসেছে।",
    es = "Al-Barr es Aquel que es infinitamente bueno y amable con sus siervos. El Corán lo nombra junto a Ar-Rahím, en las palabras de la gente del Paraíso.",
    pt = "Al-Barr é Aquele que é infinitamente bom e gentil com os Seus servos. O Alcorão o nomeia junto a Ar-Rahim, nas palavras do povo do Paraíso."),
  // 80. At-Tawwab
  explain("2:37",
    en = "At-Tawwab is the One who turns to His servants with acceptance whenever they turn back to Him. He accepts repentance and never tires of it.",
    ar = "التواب هو الذي يقبل توبة عباده كلما رجعوا إليه. يقبل التوبة ولا يمل منها.",
    bn = "আত-তাওয়াব তিনি, যিনি বান্দারা যতবার তাঁর দিকে ফেরে, ততবার তাদের দিকে ফিরে তওবা কবুল করেন। তিনি তওবা গ্রহণ করেন এবং কখনো বিরক্ত হন না।",
    es = "At-Tawwáb es Aquel que se vuelve hacia sus siervos con aceptación cada vez que ellos se vuelven a Él. Acepta el arrepentimiento y nunca se cansa de ello.",
    pt = "At-Tawwab é Aquele que se volta para os Seus servos com aceitação sempre que eles se voltam para Ele. Aceita o arrependimento e nunca se cansa disso."),
  // 81. Al-Muntaqim
  explain("3:4",
    en = "Al-Muntaqim is the One who exacts retribution from the wrongdoers, by His justice. The Qur'an warns that He is Mighty and the Lord of retribution.",
    ar = "المنتقم هو الذي ينتقم من الظالمين بعدله. وقد حذّر القرآن بأنه عزيز ذو انتقام.",
    bn = "আল-মুনতাকিম তিনি, যিনি নিজের ন্যায়বিচারে জালিমদের কাছ থেকে প্রতিশোধ নেন। কুরআন সতর্ক করেছে যে তিনি পরাক্রমশালী ও প্রতিশোধ গ্রহণকারী।",
    es = "Al-Muntaqim es Aquel que toma represalia contra los injustos, con su justicia. El Corán advierte que es Poderoso y Señor de la retribución.",
    pt = "Al-Muntaqim é Aquele que toma retaliação dos injustos, com a Sua justiça. O Alcorão adverte que Ele é Poderoso e Senhor da retribuição."),
  // 82. Al-Afuww
  explain("4:149",
    en = "Al-Afuww is the One who wipes out sins and passes over them, with no trace left behind. He pardons even though He is fully able to hold people to account.",
    ar = "العفو هو الذي يمحو الذنوب ويتجاوز عنها فلا يبقى لها أثر. يعفو وهو قادر على المحاسبة.",
    bn = "আল-আফুউ তিনি, যিনি গুনাহ মুছে দেন ও ক্ষমা করেন, কোনো চিহ্নও রাখেন না। হিসাব নেওয়ার পূর্ণ ক্ষমতা থাকা সত্ত্বেও তিনি মাফ করেন।",
    es = "Al-Afúw es Aquel que borra los pecados y los pasa por alto, sin dejar rastro. Perdona aunque es plenamente capaz de pedir cuentas.",
    pt = "Al-Afuww é Aquele que apaga os pecados e os releva, sem deixar vestígio. Perdoa embora seja plenamente capaz de pedir contas."),
  // 83. Ar-Ra'uf
  explain("2:143",
    en = "Ar-Ra'uf is the One whose mercy is gentle and tender toward His servants. He lightens their burdens and does not ask more than they can bear.",
    ar = "الرءوف هو شديد الرحمة والرأفة بعباده. يخفف عنهم ولا يكلفهم فوق طاقتهم.",
    bn = "আর-রাউফ তিনি, যাঁর দয়া বান্দাদের প্রতি কোমল ও স্নেহপূর্ণ। তিনি তাদের বোঝা হালকা করেন এবং সাধ্যের বাইরে কিছু চাপান না।",
    es = "Ar-Ra'úf es Aquel cuya misericordia es suave y tierna con sus siervos. Aligera sus cargas y no les pide más de lo que pueden soportar.",
    pt = "Ar-Ra'uf é Aquele cuja misericórdia é suave e terna com os Seus servos. Alivia os seus fardos e não lhes pede mais do que podem suportar."),
  // 84. Malik-ul-Mulk
  explain("3:26",
    en = "Malik-ul-Mulk is the Owner of all sovereignty, who gives it to whom He wills and takes it from whom He wills. Every kingdom on earth is only lent by Him.",
    ar = "مالك الملك هو صاحب الملك كله، يؤتيه من يشاء وينزعه ممن يشاء. وكل ملك في الأرض عارية منه.",
    bn = "মালিকুল মুলক সব সার্বভৌমত্বের মালিক, যিনি যাকে ইচ্ছা তা দেন এবং যার কাছ থেকে ইচ্ছা তা কেড়ে নেন। পৃথিবীর সব রাজত্ব কেবল তাঁর দেওয়া আমানত।",
    es = "Malik al-Mulk es el Dueño de toda soberanía, que la da a quien quiere y se la quita a quien quiere. Todo reino de la tierra es solo un préstamo suyo.",
    pt = "Malik-ul-Mulk é o Dono de toda soberania, que a dá a quem quer e a tira de quem quer. Todo reino da terra é apenas um empréstimo d'Ele."),
  // 85. Dhul-Jalali wal-Ikram
  explain("55:78",
    en = "Dhul-Jalali wal-Ikram is the Lord of Majesty and Honor, who is both greatly exalted and generous to His servants. His majesty does not keep His kindness from them.",
    ar = "ذو الجلال والإكرام هو صاحب العظمة الذي يكرم عباده. فعظمته لا تمنع إحسانه إليهم.",
    bn = "যুল-জালালি ওয়াল-ইকরাম মহিমা ও সম্মানের অধিকারী, যিনি একই সঙ্গে সুমহান এবং বান্দাদের প্রতি দানশীল। তাঁর মহিমা তাঁর দয়াকে বাধা দেয় না।",
    es = "Du-l-Yalál wa-l-Ikrám es el Señor de la Majestad y la Generosidad, que es a la vez sumamente excelso y generoso con sus siervos. Su majestad no impide su bondad hacia ellos.",
    pt = "Dhul-Jalali wal-Ikram é o Senhor da Majestade e da Generosidade, que é ao mesmo tempo sumamente exaltado e generoso com os Seus servos. A Sua majestade não impede a Sua bondade para com eles."),
  // 86. Al-Muqsit
  explain("3:18",
    en = "Al-Muqsit is the One who is just and who upholds justice in all that He decrees. His judgment gives each one their due.",
    ar = "المقسط هو العادل الذي يقيم العدل في كل ما يقضيه. فيعطي كل ذي حق حقه.",
    bn = "আল-মুকসিত তিনি, যিনি ন্যায়পরায়ণ এবং তাঁর সব ফয়সালায় ন্যায় প্রতিষ্ঠা করেন। তাঁর বিচারে প্রত্যেকে তার প্রাপ্য পায়।",
    es = "Al-Muqsit es Aquel que es justo y que sostiene la justicia en todo lo que decreta. Su juicio da a cada uno lo que le corresponde.",
    pt = "Al-Muqsit é Aquele que é justo e que sustenta a justiça em tudo o que decreta. O Seu julgamento dá a cada um o que lhe cabe."),
  // 87. Al-Jami'
  explain("3:9",
    en = "Al-Jami' is the One who will gather all people on a day about which there is no doubt. He also brings together what is scattered.",
    ar = "الجامع هو الذي يجمع الناس ليوم لا ريب فيه. وهو الذي يؤلف بين المتفرقات.",
    bn = "আল-জামি' তিনি, যিনি সব মানুষকে সেই দিনের জন্য একত্র করবেন, যে দিনে কোনো সন্দেহ নেই। তিনি বিক্ষিপ্ত বিষয়কেও একত্র করেন।",
    es = "Al-Yámi' es Aquel que reunirá a todas las personas en un día sobre el que no hay duda. También une lo que está disperso.",
    pt = "Al-Jami' é Aquele que reunirá todas as pessoas num dia sobre o qual não há dúvida. Também une o que está disperso."),
  // 88. Al-Ghani
  explain("35:15",
    en = "Al-Ghani is the One who has no need of anything, while all others are in need of Him. His wealth never decreases by giving.",
    ar = "الغني هو الذي لا يحتاج إلى شيء، وكل ما سواه محتاج إليه. ولا ينقص غناه بالعطاء.",
    bn = "আল-গানিয়্য তিনি, যাঁর কিছুরই প্রয়োজন নেই, অথচ অন্য সবাই তাঁর মুখাপেক্ষী। দান করলে তাঁর ভান্ডার কমে না।",
    es = "Al-Ganí es Aquel que no necesita nada, mientras que todos los demás lo necesitan a Él. Su riqueza no disminuye por dar.",
    pt = "Al-Ghani é Aquele que não precisa de nada, enquanto todos os outros precisam d'Ele. A Sua riqueza não diminui por dar."),
  // 89. Al-Mughni
  explain("9:28",
    en = "Al-Mughni is the One who enriches whom He wills from His bounty, and frees them from need. True sufficiency comes from Him.",
    ar = "المغني هو الذي يغني من يشاء من عباده من فضله ويكفيهم الحاجة. والكفاية الحقيقية منه.",
    bn = "আল-মুগনী তিনি, যিনি যাকে ইচ্ছা নিজের অনুগ্রহে অভাবমুক্ত করেন। প্রকৃত প্রাচুর্য তাঁর কাছ থেকেই আসে।",
    es = "Al-Mugní es Aquel que enriquece a quien quiere con su generosidad y lo libera de la necesidad. La verdadera suficiencia viene de Él.",
    pt = "Al-Mughni é Aquele que enriquece a quem quer com a Sua generosidade e o liberta da necessidade. A verdadeira suficiência vem d'Ele."),
  // 90. Al-Mani'
  explain(null,
    en = "Al-Mani' is the One who withholds what He wills, whenever there is wisdom in doing so. What He withholds is also a form of care, even if we do not see it. It is known from the transmitted list.",
    ar = "المانع هو الذي يمنع ما يشاء لحكمة. وما يمنعه قد يكون رعاية منه ولو لم نعلم. والاسم معروف من القائمة المروية.",
    bn = "আল-মানি' তিনি, যিনি প্রজ্ঞার কারণে যা ইচ্ছা আটকে রাখেন। তিনি যা আটকান, তা-ও এক ধরনের যত্ন, যদিও আমরা তা বুঝি না। নামটি বর্ণিত তালিকা থেকে জানা যায়।",
    es = "Al-Máni' es Aquel que retiene lo que quiere cuando hay sabiduría en ello. Lo que retiene es también una forma de cuidado, aunque no lo veamos. Se conoce por la lista transmitida.",
    pt = "Al-Mani' é Aquele que retém o que quer quando há sabedoria nisso. O que retém é também uma forma de cuidado, ainda que não o vejamos. É conhecido pela lista transmitida."),
  // 91. Ad-Darr
  explain(null,
    en = "Ad-Darr is the One who decrees harm and hardship by His wisdom, and no one can remove it but Him. It is always understood together with An-Nafi', as both are in His hand. It is known from the transmitted list.",
    ar = "الضار هو الذي يقدّر الضر والشدة بحكمته، ولا يكشفه غيره. ويُفهم دائمًا مع النافع، فكلاهما بيده. والاسم معروف من القائمة المروية.",
    bn = "আদ-দার্র তিনি, যিনি নিজের প্রজ্ঞায় ক্ষতি ও কষ্ট নির্ধারণ করেন, আর তিনি ছাড়া কেউ তা দূর করতে পারে না। এটি সবসময় আন-নাফি'র সঙ্গে বোঝা হয়, কারণ দুটোই তাঁর হাতে। নামটি বর্ণিত তালিকা থেকে জানা যায়।",
    es = "Ad-Dárr es Aquel que decreta el daño y la dificultad con su sabiduría, y nadie puede quitarlos salvo Él. Se entiende siempre junto a An-Náfi', pues ambos están en su mano. Se conoce por la lista transmitida.",
    pt = "Ad-Darr é Aquele que decreta o dano e a dificuldade com a Sua sabedoria, e ninguém pode removê-los senão Ele. É sempre entendido junto a An-Nafi', pois ambos estão em Suas mãos. É conhecido pela lista transmitida."),
  // 92. An-Nafi'
  explain(null,
    en = "An-Nafi' is the One who decrees benefit and good for whom He wills. No benefit reaches anyone except by His permission. It is known from the transmitted list.",
    ar = "النافع هو الذي يقدّر النفع والخير لمن يشاء. فلا ينال أحد نفعًا إلا بإذنه. والاسم معروف من القائمة المروية.",
    bn = "আন-নাফি' তিনি, যিনি যাকে ইচ্ছা উপকার ও কল্যাণ নির্ধারণ করেন। তাঁর অনুমতি ছাড়া কেউ কোনো উপকার পায় না। নামটি বর্ণিত তালিকা থেকে জানা যায়।",
    es = "An-Náfi' es Aquel que decreta el beneficio y el bien para quien Él quiere. Ningún beneficio llega a nadie salvo con su permiso. Se conoce por la lista transmitida.",
    pt = "An-Nafi' é Aquele que decreta o benefício e o bem para quem Ele quer. Nenhum benefício chega a ninguém senão com a Sua permissão. É conhecido pela lista transmitida."),
  // 93. An-Nur
  explain("24:35",
    en = "An-Nur is the One who is the Light of the heavens and the earth. By His light, hearts are guided and the truth becomes clear.",
    ar = "النور هو الذي هو نور السماوات والأرض. وبنوره تهتدي القلوب ويتضح الحق.",
    bn = "আন-নূর তিনি, যিনি আসমান ও যমীনের আলো। তাঁর আলোতেই হৃদয় পথ পায় এবং সত্য স্পষ্ট হয়।",
    es = "An-Núr es Aquel que es la Luz de los cielos y de la tierra. Con su luz los corazones son guiados y la verdad se vuelve clara.",
    pt = "An-Nur é Aquele que é a Luz dos céus e da terra. Com a Sua luz os corações são guiados e a verdade se torna clara."),
  // 94. Al-Hadi
  explain("25:31",
    en = "Al-Hadi is the One who guides whom He wills to the truth, and shows creatures what they need. It is enough to have the Lord as a guide.",
    ar = "الهادي هو الذي يهدي من يشاء إلى الحق ويدل المخلوقات على ما يحتاجون. وكفى بربك هاديًا.",
    bn = "আল-হাদী তিনি, যিনি যাকে ইচ্ছা সত্যের পথ দেখান এবং সৃষ্টিকে তাদের প্রয়োজনীয় পথ জানান। পথপ্রদর্শক হিসেবে তোমার রবই যথেষ্ট।",
    es = "Al-Hádi es Aquel que guía a quien quiere hacia la verdad, y muestra a las criaturas lo que necesitan. Basta tener al Señor como guía.",
    pt = "Al-Hadi é Aquele que guia a quem quer para a verdade, e mostra às criaturas o que precisam. Basta ter o Senhor como guia."),
  // 95. Al-Badi'
  explain("2:117",
    en = "Al-Badi' is the One who originates the heavens and the earth without any earlier pattern. When He decides a thing, He only says to it Be, and it is.",
    ar = "البديع هو الذي أبدع السماوات والأرض على غير مثال سابق. وإذا قضى أمرًا فإنما يقول له كن فيكون.",
    bn = "আল-বাদী' তিনি, যিনি আগের কোনো নমুনা ছাড়াই আসমান ও যমীন উদ্ভাবন করেছেন। তিনি কোনো কিছু স্থির করলে শুধু বলেন হও, আর তা হয়ে যায়।",
    es = "Al-Badí' es Aquel que originó los cielos y la tierra sin ningún modelo previo. Cuando decide algo, solo le dice Sé, y es.",
    pt = "Al-Badi' é Aquele que originou os céus e a terra sem nenhum modelo prévio. Quando decide algo, apenas lhe diz Sê, e é."),
  // 96. Al-Baqi
  explain("55:27",
    en = "Al-Baqi is the One who remains forever and never perishes. Everything on earth will pass away, and only His Face remains.",
    ar = "الباقي هو الدائم الذي لا يفنى. فكل من عليها فان، ويبقى وجه ربك.",
    bn = "আল-বাকী তিনি, যিনি চিরকাল থাকেন এবং কখনো ধ্বংস হন না। পৃথিবীর সবকিছু নশ্বর, শুধু তাঁর সত্তাই থেকে যাবে।",
    es = "Al-Báqi es Aquel que permanece para siempre y nunca perece. Todo lo que hay sobre la tierra desaparecerá, y solo quedará su Rostro.",
    pt = "Al-Baqi é Aquele que permanece para sempre e nunca perece. Tudo o que há sobre a terra desaparecerá, e somente a Sua Face permanecerá."),
  // 97. Al-Warith
  explain("15:23",
    en = "Al-Warith is the One who remains after all creation has gone, and to whom everything returns. He is the final inheritor of the heavens and the earth.",
    ar = "الوارث هو الذي يبقى بعد فناء الخلق، وإليه يرجع كل شيء. فهو وارث السماوات والأرض.",
    bn = "আল-ওয়ারিস তিনি, যিনি সব সৃষ্টির বিলুপ্তির পরও থাকবেন এবং যাঁর কাছে সবকিছু ফিরে যাবে। তিনিই আসমান ও যমীনের চূড়ান্ত উত্তরাধিকারী।",
    es = "Al-Wáriz es Aquel que permanece cuando toda la creación ha desaparecido, y a quien todo regresa. Él es el heredero final de los cielos y de la tierra.",
    pt = "Al-Warith é Aquele que permanece depois que toda a criação se foi, e a quem tudo retorna. Ele é o herdeiro final dos céus e da terra."),
  // 98. Ar-Rashid
  explain(null,
    en = "Ar-Rashid is the One whose guidance leads to the right course, and whose decrees are all set in wisdom. It is known from the transmitted list.",
    ar = "الرشيد هو الذي يهدي إلى طريق الرشد، وكل أقداره جارية على الحكمة. والاسم معروف من القائمة المروية.",
    bn = "আর-রাশীদ তিনি, যাঁর হিদায়াত সঠিক পথে পৌঁছায় এবং যাঁর সব সিদ্ধান্ত প্রজ্ঞার ওপর প্রতিষ্ঠিত। নামটি বর্ণিত তালিকা থেকে জানা যায়।",
